using System.Text.Json;
using Xunit;

namespace Tamp.Spfx.Tests;

/// <summary>
/// <see cref="SpfxDebugUrl"/> against URLs the SPFx rig itself computed (<c>Fixtures/debug-urls/vectors.json</c>,
/// generated by <c>generate.cjs</c> from <c>@microsoft/spfx-heft-plugins</c> 1.24.1), plus the two places it
/// deliberately differs.
/// </summary>
public sealed class SpfxDebugUrlTests
{
    private static readonly string VectorsPath = Path.Combine(Fixture.Dir, "debug-urls", "vectors.json");

    public sealed record Vector(string Name, JsonElement Serve, string? Configuration, string? TenantDomain, string? Expected)
    {
        public override string ToString() => Name;
    }

    public static IEnumerable<object[]> Vectors()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(VectorsPath));
        foreach (var v in doc.RootElement.GetProperty("vectors").EnumerateArray())
        {
            yield return new object[]
            {
                new Vector(
                    v.GetProperty("name").GetString()!,
                    v.GetProperty("serve").Clone(),
                    v.GetProperty("configuration").ValueKind == JsonValueKind.Null ? null : v.GetProperty("configuration").GetString(),
                    v.GetProperty("tenantDomain").ValueKind == JsonValueKind.Null ? null : v.GetProperty("tenantDomain").GetString(),
                    v.GetProperty("expected").ValueKind == JsonValueKind.Null ? null : v.GetProperty("expected").GetString()),
            };
        }
    }

    [Theory]
    [MemberData(nameof(Vectors))]
    public void Matches_The_Rig(Vector v)
    {
        var serve = SpfxServeConfig.Parse(v.Serve.GetRawText());

        if (v.TenantDomain is null && v.Expected is not null && v.Expected.Contains("{tenantdomain}", StringComparison.Ordinal))
        {
            // The rig yields https://{tenantdomain}/...; we refuse instead (deliberate difference).
            var ex = Assert.Throws<InvalidOperationException>(() => SpfxDebugUrl.Build(serve, v.Configuration, tenantDomain: null));
            Assert.Contains(SpfxServeConfig.TenantDomainVariable, ex.Message, StringComparison.Ordinal);
            return;
        }

        Assert.Equal(v.Expected, SpfxDebugUrl.Build(serve, v.Configuration, v.TenantDomain ?? NoTenant(v)));
    }

    // A vector with no tenant domain has no placeholder; pass a value anyway so a SPFX_SERVE_TENANT_DOMAIN set on the
    // machine can't change the result.
    private static string? NoTenant(Vector v) => v.Serve.GetRawText().Contains("{tenantdomain}", StringComparison.OrdinalIgnoreCase) ? null : "unused.sharepoint.com";

    [Fact]
    public void There_Are_Vectors_For_Every_Extension_Kind()
    {
        var names = Vectors().Select(o => ((Vector)o[0]).Name).ToList();
        Assert.Contains(names, n => n.StartsWith("form customizer: edit", StringComparison.Ordinal));
        Assert.Contains(names, n => n.Contains("application customizer", StringComparison.Ordinal));
        Assert.Contains(names, n => n.Contains("field customizers", StringComparison.Ordinal));
        Assert.Contains(names, n => n.Contains("web part", StringComparison.Ordinal));
        Assert.True(names.Count >= 15);
    }

    private const string FormServe = """
        {
          // comments are allowed, as in generated serve.json files
          "port": 4321, "https": true,
          "serveConfigurations": {
            "default": { "pageUrl": "https://{tenantDomain}/_layouts/15/SPListForm.aspx",
                         "formCustomizer": { "componentId": "2875713c-2c49-4baf-9725-fcc44d531e58", "PageType": 8, "RootFolder": "/sites/s/Lists/L" } },
            "myForm_EditForm": { "pageUrl": "https://{tenantDomain}/_layouts/15/SPListForm.aspx",
                         "formCustomizer": { "componentId": "2875713c-2c49-4baf-9725-fcc44d531e58", "PageType": 6, "RootFolder": "/sites/s/Lists/L", "ID": 7 } },
          },
        }
        """;

    [Fact]
    public void Unknown_Configuration_Throws_With_The_Names_Instead_Of_Falling_Back()
    {
        var serve = SpfxServeConfig.Parse(FormServe);
        var ex = Assert.Throws<KeyNotFoundException>(() => SpfxDebugUrl.Build(serve, "myForm_EditFrom", "contoso.sharepoint.com"));
        Assert.Contains("default, myForm_EditForm", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Explicit_Manifests_Url_Points_At_The_Running_Server()
    {
        var url = SpfxDebugUrl.Build(SpfxServeConfig.Parse(FormServe), "myForm_EditForm", "contoso.sharepoint.com",
            manifestsUrl: "https://localhost:5555/temp/build/manifests.js");
        Assert.StartsWith("https://contoso.sharepoint.com/_layouts/15/SPListForm.aspx?debugManifestsFile=https%3A%2F%2Flocalhost%3A5555%2F", url, StringComparison.Ordinal);
        Assert.Contains("&PageType=6&RootFolder=%2Fsites%2Fs%2FLists%2FL&ID=7", url, StringComparison.Ordinal);
        Assert.DoesNotContain("debug=true", url, StringComparison.Ordinal);
    }

    [Fact]
    public void No_Page_Url_Anywhere_Throws()
    {
        var ex = Assert.Throws<InvalidOperationException>(() => SpfxDebugUrl.Build(SpfxServeConfig.Parse("""{ "port": 4321 }""")));
        Assert.Contains("initialPage", ex.Message, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("not a url")]
    [InlineData("ftp://contoso.sharepoint.com/x")]
    [InlineData("/sites/relative")]
    public void Non_Http_Page_Urls_Are_Refused(string page)
    {
        var serve = SpfxServeConfig.Parse($$"""{ "initialPage": "{{page}}" }""");
        Assert.Throws<InvalidOperationException>(() => SpfxDebugUrl.Build(serve, tenantDomain: "unused"));
    }

    [Fact]
    public void A_Form_Field_That_Collides_With_A_Different_Value_Throws_Like_The_Rig()
    {
        var serve = SpfxServeConfig.Parse("""
            { "serveConfigurations": { "default": { "pageUrl": "https://contoso.sharepoint.com/x",
              "formCustomizer": { "componentId": "c", "noredir": "false" } } } }
            """);
        Assert.Throws<InvalidOperationException>(() => SpfxDebugUrl.Build(serve, tenantDomain: "unused"));
    }

    [Fact]
    public void Tenant_Domain_With_Dollar_Signs_Is_Taken_Literally()
    {
        Assert.Equal("https://a$1b/x", SpfxDebugUrl.ReplaceTenantDomain("https://{tenantDomain}/x", "a$1b"));
        Assert.Equal("https://{tenantDomain}/x", SpfxDebugUrl.ReplaceTenantDomain("https://{tenantDomain}/x", null));
    }

    [Fact]
    public void Serve_Config_Reads_Rig_Defaults_And_Precedence()
    {
        var defaults = SpfxServeConfig.Parse("{}");
        Assert.Equal(("localhost", 4321, false), (defaults.Hostname, defaults.Port, defaults.Https));
        Assert.Equal("http://localhost:4321/temp/build/manifests.js", defaults.ManifestsUrl());

        var ip = SpfxServeConfig.Parse("""{ "ipAddress": "0.0.0.0", "https": true }""");
        Assert.Equal("0.0.0.0", ip.Hostname);
        var both = SpfxServeConfig.Parse("""{ "ipAddress": "0.0.0.0", "hostname": "dev.localhost", "port": 4500 }""");
        Assert.Equal("http://dev.localhost:4500/temp/build/manifests.js", both.ManifestsUrl());

        var tenantHost = SpfxServeConfig.Parse("""{ "hostname": "{tenantDomain}", "https": true }""");
        Assert.Equal("https://contoso.sharepoint.com:4321/temp/build/manifests.js", tenantHost.ManifestsUrl("contoso.sharepoint.com"));
    }

    [Theory]
    [InlineData("""{ "port": "4321" }""")]
    [InlineData("""{ "port": 0 }""")]
    [InlineData("""{ "port": 70000 }""")]
    [InlineData("""[1, 2]""")]
    [InlineData("""{ nope""")]
    public void Unusable_Serve_Json_Is_Refused(string json)
    {
        Assert.Throws<InvalidDataException>(() => SpfxServeConfig.Parse(json));
    }

    [Fact]
    public void Load_Reads_Config_Serve_Json_And_Defaults_When_Missing()
    {
        using var t = new TempDir();
        Assert.Equal(4321, SpfxServeConfig.Load(t.Path).Port);
        Assert.Null(SpfxServeConfig.Load(t.Path).SourcePath);

        Directory.CreateDirectory(Path.Combine(t.Path, "config"));
        File.WriteAllText(Path.Combine(t.Path, "config", "serve.json"), "﻿" + FormServe);
        var serve = SpfxServeConfig.Load(t.Path);
        Assert.Equal(new[] { "default", "myForm_EditForm" }, serve.Configurations.Select(c => c.Name));
        Assert.True(serve.Https);
        Assert.NotNull(serve.Find("myForm_EditForm")!.FormCustomizer);
        Assert.Null(serve.Find("myForm_EditForm")!.CustomActions);
        Assert.EndsWith(Path.Combine("config", "serve.json"), serve.SourcePath, StringComparison.Ordinal);
    }
}
